package com.example.campusmaintenance.filter;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.slf4j.*; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.UUID;
@Component public class CorrelationIdFilter extends OncePerRequestFilter {private static final Logger log=LoggerFactory.getLogger(CorrelationIdFilter.class); protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String id=req.getHeader("X-Correlation-ID");if(id==null||id.isBlank())id=UUID.randomUUID().toString();MDC.put("correlationId",id);res.setHeader("X-Correlation-ID",id);long start=System.currentTimeMillis();try{log.info("REQUEST {} {}",req.getMethod(),req.getRequestURI());chain.doFilter(req,res);}finally{log.info("RESPONSE {} {} status={} durationMs={}",req.getMethod(),req.getRequestURI(),res.getStatus(),System.currentTimeMillis()-start);MDC.remove("correlationId");}}}
